import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

avg_pool1d_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void avg_pool1d_kernel(
    const float* __restrict__ input,
    float* __restrict__ output,
    int batch_size,
    int channels,
    int input_length,
    int output_length,
    int kernel_size,
    int stride,
    int padding
) {
    int out_size = batch_size * channels * output_length;
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx >= out_size) return;

    int row = idx / output_length;  // which (N*C) index
    int col = idx % output_length;  // position in the output length dimension

    int input_offset = row * input_length;
    int kernel_start = col * stride - padding;
    int kernel_end = kernel_start + kernel_size;

    float sum_val = 0.0f;
    int count = 0;
    for (int i = kernel_start; i < kernel_end; i++) {
        if (i >= 0 && i < input_length) {
            sum_val += input[input_offset + i];
            count++;
        }
    }
    output[idx] = count > 0 ? (sum_val / count) : 0.0f;
}

torch::Tensor avg_pool1d_cuda(
    torch::Tensor input,
    int kernel_size,
    int stride,
    int padding
) {
    const auto batch_size = input.size(0);
    const auto channels = input.size(1);
    const auto input_length = input.size(2);
    int output_length = (input_length + 2 * padding - kernel_size) / stride + 1;

    auto output = torch::zeros({batch_size, channels, output_length}, input.options());

    int out_size = batch_size * channels * output_length;
    const int block_size = 256;
    const int grid_size = (out_size + block_size - 1) / block_size;

    avg_pool1d_kernel<<<grid_size, block_size>>>(
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        batch_size,
        channels,
        input_length,
        output_length,
        kernel_size,
        stride,
        padding
    );

    return output;
}
"""

avg_pool1d_cpp_source = "torch::Tensor avg_pool1d_cuda(torch::Tensor input, int kernel_size, int stride, int padding);"

avg_pool1d_module = load_inline(
    name="avg_pool1d_module",
    cpp_sources=avg_pool1d_cpp_source,
    cuda_sources=avg_pool1d_source,
    functions=["avg_pool1d_cuda"],
    verbose=False
)

class ModelNew(nn.Module):
    """
    Custom model that performs 1D Average Pooling with a custom CUDA kernel.
    """
    def __init__(self, kernel_size: int, stride: int = 1, padding: int = 0):
        super(ModelNew, self).__init__()
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding
        self.avg_pool_cuda = avg_pool1d_module

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self.avg_pool_cuda.avg_pool1d_cuda(
            x, self.kernel_size, self.stride, self.padding
        )
